 grid.addEventListener('focusout',event=>{const node=event.target;if(!node.matches?.('[data-required]'))return;const hint=node.closest('label')?.querySelector('.license-field-error');if(!hint)return;const empty=!String(node.value||'').trim();node.toggleAttribute('aria-invalid',empty);if(empty){hint.classList.remove('license-field-help');hint.textContent='Este dato es obligatorio.';}else if(hint.textContent==='Este dato es obligatorio.')hint.textContent='';});
